/* Request markers for current bounds/zoom, render them,
 * and keep the date sliders in sync with the viewport.
 */
function updateMarkers(){
  // Don't load markers if home overlay is still showing (unless in track view)
  if (!homeOverlayDismissed && !isTrackView && shouldShowHomeOverlay()) {
    return;
  }

  const loadingEl = document.getElementById('loadingOverlay');
  if (loadingEl) loadingEl.style.display='block';

  if (markerStreamSource) markerStreamSource.close();
  if (window.markerStreamSources) {
    window.markerStreamSources.forEach(source => source.close());
  }
  window.markerStreamSources = [];

  const zoom   = map.getZoom();
  const bounds = map.getBounds();

  const baseParams = {
    zoom  : zoom,
    minLat: bounds.getSouthWest().lat,
    minLon: bounds.getSouthWest().lng,
    maxLat: bounds.getNorthEast().lat,
    maxLon: bounds.getNorthEast().lng
  };

  // When viewing a specific track, use world bounds to load ALL markers, not just viewport
  if (currentTrackID) {
    baseParams.trackID = currentTrackID;
    baseParams.minLat = -90;
    baseParams.minLon = -180;
    baseParams.maxLat = 90;
    baseParams.maxLon = 180;
  }

  // When viewing multiple tracks, load all markers for those tracks
  if (currentTrackIDs && currentTrackIDs.length > 0) {
    baseParams.trackIDs = currentTrackIDs.join(',');
    baseParams.minLat = -90;
    baseParams.minLon = -180;
    baseParams.maxLat = 90;
    baseParams.maxLon = 180;
  }

  // Pass show filter to backend (e.g., show=rt skips historical data)
  const showParam = new URLSearchParams(window.location.search).get('show');
  if (showParam) {
    baseParams.show = showParam;
  }

  const savedRange = loadDateRangeState();

  // Skip if viewport hasn't meaningfully changed (prevents unnecessary redraws)
  const newViewportKey = getViewportKey();
  const newFilterState = getFilterStateKey();
  const filterChanged = lastFilterState !== newFilterState;

  if (lastViewportKey === newViewportKey && lastFilterState === newFilterState && !currentTrackID && !currentTrackIDs) {
    // Viewport and filters unchanged in global view - skip full redraw
    return;
  }

  // In track view, only reload if filters changed or this is the first load
  // We load ALL markers at once, so viewport changes don't require reloading
  if ((currentTrackID || currentTrackIDs) && !filterChanged && Object.keys(circleMarkers).length > 0) {
    // Track view: markers already loaded and filters unchanged - skip reload
    return;
  }

  lastViewportKey = newViewportKey;

